#define TMR_IRQ_COUNT		4	// number of hardware timer available for match register use.

/*--------------------------------------------------------------------*/

#define TMR_IRQ_IR	(*(volatile unsigned long *)(TMR3_BASE_ADDR + 0x00))
#define TMR_IRQ_TC	(*(volatile unsigned long *)(TMR3_BASE_ADDR + 0x08))
#define TMR_IRQ_MCR	(*(volatile unsigned long *)(TMR3_BASE_ADDR + 0x14))
#define TMR_IRQ_MR	(*(volatile unsigned long *)(TMR3_BASE_ADDR + 0x18 + 4*(tmr->index)))


/*--------------------------------------------------------------------*/

#define TMR_IRQ_MAX_TIMEOUT			3*1000*72

/*--------------------------------------------------------------------*/

typedef struct s_Tmr_Irq
{
	Tmr_Irq_Func service_vector; 
	UInt8        index         ;

}*Tmr_Irq;

